class Solution {
    private String key(String word){
        StringBuilder value=new StringBuilder();
        for(int i=1;i<word.length();i++)value.append(word.charAt(i)-word.charAt(i-1)).append(',');
        return value.toString();
    }
    public String oddString(String[] words){
        Map<String,Integer> frequency=new HashMap<>();
        for(String word:words)frequency.merge(key(word),1,Integer::sum);
        for(String word:words)if(frequency.get(key(word))==1)return word;
        return "";
    }
}

code.kotlin:
class Solution {
    fun oddString(words:Array<String>):String{
        val key={
            word:String->buildString{
                for(i in 1 until word.length)append(word[i]-word[i-1]).append(',')
            }
        };
        val frequency=HashMap<String,Int>();
        for(word in words){
            val k=key(word);
            frequency[k]=(frequency[k]?:0)+1
        };
        return words.first{
            frequency[key(it)]==1
        }
    }
}

